UNION ALL SELECT UNISTR('90% \0645\0646 \0627\0644\0645\0631\0627\062A \062E\0644\0627\0644 (\0645\0644\0651\064A \062B\0627\0646\064A\0629)') AR, '90% of views within (ms)' EN FROM DUAL
