UNION ALL SELECT UNISTR('\064A\064F\062D\0633\0628 \0623\064A\0627\0645\0627\064B') AR, 'Counts as days' EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\064F\062D\0633\0628 \062D\0636\0648\0631\0647') AR, 'Counts for attendance' EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\064F\062D\0633\0628 \0643\0645 \064A\0648\0645 \0639\0645\0644') AR, 'Counts as work days' EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\064F\0631\0627\062C\064E\0639 \0641\064A \00AB\062D\0631\0643\0627\062A \0627\0644\0631\0635\064A\062F\00BB \062B\0645 \064A\064F\0631\062D\064E\0651\0644\060C \0623\0648 \062A\0644\0642\0627\0626\064A\0627\064B \0623\0648\0644 \0643\0644 \0634\0647\0631.') AR, TO_CHAR(UNISTR('Reviewed in \00ABBalance movements\00BB then posted, or by itself on the 1st.')) EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\064F\0631\0633\0644 \0625\0644\0649 \0627\0644\062C\0647\0627\0632 \0639\0646\0648\0627\0646 \0627\0644\062E\0627\062F\0645 \0648\0645\0646\0641\0630\0647 \0644\064A\062A\0635\0644 \0628\0647 \0645\0646 \0627\0644\0622\0646. \062C\0647\0627\0632 \064A\064F\0648\062C\064E\0651\0647 \0625\0644\0649 \0639\0646\0648\0627\0646 \062E\0627\0637\0626 \0644\0627 \064A\0639\0648\062F \0625\0644\0627 \0645\0646 \0634\0627\0634\062A\0647\060C \0641\062A\0623\0643\062F \0645\0646 \0627\0644\0639\0646\0648\0627\0646 \0642\0628\0644 \0627\0644\0625\0631\0633\0627\0644.') AR, 'The terminal is sent the server address and port and connects to it from now on. A terminal sent to a wrong address comes back only from its own screen: check the address first.' EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\064F\0636\0628\0637 \0647\0630\0627 \0639\0644\0649 \0627\0644\062C\0647\0627\0632 \0646\0641\0633\0647 \0645\0646 \0634\0627\0634\062A\0647\061B \0627\0644\0628\0631\0646\0627\0645\062C \0644\0627 \064A\0642\0631\0624\0647 \0648\0644\0627 \064A\063A\064A\0651\0631\0647 \0639\0646 \0628\064F\0639\062F.') AR, 'This is set on the terminal itself, from its screen; the program cannot read or change it remotely.' EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\064F\0637\0628\0642 \0627\0644\062A\0639\062F\064A\0644 \0647\0646\0627 \0645\0646 \0627\0644\064A\0648\0645\060C \0648\0644\0627 \064A\062A\063A\064A\0631 \062D\0633\0627\0628 \0627\0644\0623\064A\0627\0645 \0627\0644\0633\0627\0628\0642\0629. \0644\062A\0627\0631\064A\062E \0622\062E\0631 \0623\0648 \0644\0641\062A\0631\0629 \0645\062D\062F\062F\0629 \0627\0633\062A\062E\062F\0645 \00AB\062A\0639\062F\064A\0644 \0628\062A\0627\0631\064A\062E \0623\0648 \0644\0641\062A\0631\0629\00BB.') AR, TO_CHAR(UNISTR('A change here applies from today; the days before are not recalculated. For another date or a set period use \201CChange by date or for a period\201D.')) EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\064F\0639\0631\0641 \0627\0644\0645\0648\0638\0641 \0628\0640') AR, 'Employee is identified by' EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\064F\0642\0628\0644 \0627\0644\062E\0631\0648\062C \0642\0628\0644 \0627\0644\0645\0648\0639\062F \0628\0640 (\062F\0642\064A\0642\0629)') AR, 'Check-out accepted before the time by (min)' EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\064F\0642\0628\0644 \0627\0644\062F\062E\0648\0644 \0642\0628\0644 \0627\0644\0645\0648\0639\062F \0628\0640 (\062F\0642\064A\0642\0629)') AR, 'Check-in accepted before the time by (min)' EN FROM DUAL
UNION ALL SELECT UNISTR('\2014 \0627\0644\0623\0648\0644\0649 \2014') AR, TO_CHAR(UNISTR('\2014 the first \2014')) EN FROM DUAL) s ON (t.AR = s.AR)
  WHEN MATCHED THEN UPDATE SET EN = s.EN WHERE t.EN <> s.EN
  WHEN NOT MATCHED THEN INSERT (AR, EN) VALUES (s.AR, s.EN);
  COMMIT;
END;
