UNION ALL SELECT UNISTR('\0627\0644\062A\0639\0631\0651\0641 \0627\0644\062A\064A \064A\062A\0639\0644\0651\0645 \0645\0646\0647\0627 \0627\0644\062C\0647\0627\0632 \0627\0644\0648\062C\0647. \0635\0648\0631\0629 JPEG \0623\0642\0644 \0645\0646 400 \0643\064A\0644\0648\0628\0627\064A\062A (\0648\064A\064F\0641\0636\0651\0644 \0646\062D\0648 480 \0628\0643\0633\0644)\061B \062A\064F\0631\0633\0644 \0625\0644\0649') AR, 'recognition photo the terminal learns the face from. A JPEG under 400 KB (about 480 pixels is best); it is sent to the' EN FROM DUAL
