UNION ALL SELECT UNISTR('\0645\0633\062A\062E\062F\0645 \0623\0628\0643\0633 \0647\0648 \0627\0644\062D\0633\0627\0628 \0627\0644\0630\064A \064A\062D\0645\0644 \0627\0633\0645 \062F\062E\0648\0644\0647 \0646\0641\0633\0647. \0627\0644\0635\0644\0627\062D\064A\0627\062A \0647\0646\0627 \062A\062D\062F\062F \0645\0646 \064A\0639\062A\0645\062F \0627\0644\0637\0644\0628\0627\062A (\0648\0645\0646 \0623\064A \0627\0644\0623\0642\0633\0627\0645) \0648\0645\0646 \064A\0639\064A\0651\0646 \0645\0633\0624\0648\0644\064A \0627\0644\0627\0639\062A\0645\0627\062F \0648\0627\0644\062D\0633\0627\0628\0627\062A. \062D\0633\0627\0628\0627\062A \0628\0631\0646\0627\0645\062C \062D\0627\0636\0631 \062A\0635\0644 \0645\0646\0647 \0648\062A\064F\0639\062F\064E\0651\0644 \0641\064A\0647. \0648\0645\0627 \062F\0627\0645 \0644\0627 \064A\0648\062C\062F \0623\064A \062D\0633\0627\0628\060C \064A\0639\062A\0645\062F \0643\0644 \0645\0633\062A\062E\062F\0645 \0643\0644 \0627\0644\0637\0644\0628\0627\062A \0643\0645\0627 \0643\0627\0646.') AR, TO_CHAR(UNISTR('An APEX user is the account with the same sign-in name. The permissions here set who approves requests (and for which departments) and who assigns approvers and accounts. The Hader program\2019s accounts come from it and are changed there. While there is no account at all, every user approves every request, as before.')) EN FROM DUAL
UNION ALL SELECT UNISTR('\0645\0633\062A\062E\062F\0645 \0623\0628\0643\0633 \0647\0648 \0627\0644\062D\0633\0627\0628 \0627\0644\0630\064A \064A\062D\0645\0644 \0627\0633\0645 \062F\062E\0648\0644\0647 \0646\0641\0633\0647. \0627\0644\0635\0644\0627\062D\064A\0627\062A \0647\0646\0627 \062A\062D\062F\062F \0645\0646 \064A\0639\062A\0645\062F \0627\0644\0637\0644\0628\0627\062A (\0648\0645\0646 \0623\064A \0627\0644\0623\0642\0633\0627\0645) \0648\0645\0646 \064A\0639\064A\0651\0646 \0645\0633\0624\0648\0644\064A \0627\0644\0627\0639\062A\0645\0627\062F \0648\0627\0644\062D\0633\0627\0628\0627\062A. \062D\0633\0627\0628\0627\062A \0646\0638\0627\0645 \0627\0644\062F\0648\0627\0645 \062A\0635\0644 \0645\0646\0647 \0648\062A\064F\0639\062F\064E\0651\0644 \0641\064A\0647. \0648\0645\0627 \062F\0627\0645 \0644\0627 \064A\0648\062C\062F \0623\064A \062D\0633\0627\0628\060C \064A\0639\062A\0645\062F \0643\0644 \0645\0633\062A\062E\062F\0645 \0643\0644 \0627\0644\0637\0644\0628\0627\062A \0643\0645\0627 \0643\0627\0646.') AR, TO_CHAR(UNISTR('An APEX user is the account with the same sign-in name. The permissions here set who approves requests (and for which departments) and who assigns approvers and accounts. The attendance system\2019s accounts come from it and are changed there. While there is no account at all, every user approves every request, as before.')) EN FROM DUAL
