UNION ALL SELECT UNISTR('\064A\062C\064A\0628 \062E\0627\062F\0645 \0627\0644\062F\0648\0627\0645 \0639\0646 \0623\0633\0626\0644\062A\0643 \0628\0635\0644\0627\062D\064A\0627\062A \062D\0633\0627\0628\0643 \0641\064A\0647. \064A\0638\0647\0631 \0627\0644\0631\062F \0628\0639\062F \0625\0639\0627\062F\0629 \062A\062D\0645\064A\0644 \0627\0644\0635\0641\062D\0629\061B \0648\0625\0646 \0637\0627\0644 \0641\0627\0636\063A\0637 \00AB\062A\062D\062F\064A\062B\00BB. \0625\0631\0641\0627\0642 \0627\0644\0645\0644\0641\0627\062A \0648\062A\0646\0632\064A\0644 \0645\0627 \064A\0635\0646\0639\0647 \0627\0644\0645\0633\0627\0639\062F \0645\0646 \0632\0631 \0627\0644\0645\0633\0627\0639\062F \0641\064A \0623\0639\0644\0649 \0627\0644\0635\0641\062D\0629.') AR, TO_CHAR(UNISTR('The attendance server answers your questions with your account\0027s permissions there. The answer appears when the page reloads; if it takes long, press \00ABRefresh\00BB. Attaching files and downloading what the assistant makes are in the assistant button at the top of the page.')) EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\062C\064A\0628 \062E\0627\062F\0645 \062D\0627\0636\0631 \0639\0646 \0623\0633\0626\0644\062A\0643 \0628\0635\0644\0627\062D\064A\0627\062A \062D\0633\0627\0628\0643 \0641\064A\0647. \064A\0638\0647\0631 \0627\0644\0631\062F \0628\0639\062F \0625\0639\0627\062F\0629 \062A\062D\0645\064A\0644 \0627\0644\0635\0641\062D\0629\061B \0648\0625\0646 \0637\0627\0644 \0641\0627\0636\063A\0637 \00AB\062A\062D\062F\064A\062B\00BB. \0625\0631\0641\0627\0642 \0627\0644\0645\0644\0641\0627\062A \0648\062A\0646\0632\064A\0644 \0645\0627 \064A\0635\0646\0639\0647 \0627\0644\0645\0633\0627\0639\062F \0645\0646 \0632\0631 \0627\0644\0645\0633\0627\0639\062F \0641\064A \0623\0639\0644\0649 \0627\0644\0635\0641\062D\0629.') AR, TO_CHAR(UNISTR('The Hader server answers your questions with your account\0027s permissions there. The answer appears when the page reloads; if it takes long, press \00ABRefresh\00BB. Attaching files and downloading what the assistant makes are in the assistant button at the top of the page.')) EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\062F\062E\0644 \0627\0644\0645\0648\0638\0641 \0645\0646 \0628\0648\0627\0628\0629 \0627\0644\0645\0624\0633\0633\0629 \062B\0645 \00AB\0627\0644\062F\062E\0648\0644 \0625\0644\0649 \0628\0648\0627\0628\062A\064A\00BB: \064A\0631\0649 \062D\0636\0648\0631\0647 \0627\0644\064A\0648\0645 \0648\0633\062C\0644\0647 \0627\0644\0634\0647\0631\064A\060C \0648\064A\0631\0633\0644 \0637\0644\0628\0627\062A\0647 \0648\064A\0631\0649 \0631\0635\064A\062F \0625\062C\0627\0632\0627\062A\0647. \0644\0627 \0643\0644\0645\0629 \0645\0631\0648\0631 \062E\0627\0635\0629 \0628\0627\0644\0628\0648\0627\0628\0629: \064A\0643\0641\064A \062F\062E\0648\0644\0647 \0625\0644\0649 \0623\0646\0638\0645\0629 \0627\0644\0645\0624\0633\0633\0629.') AR, TO_CHAR(UNISTR('An employee signs in from the organization\2019s portal, then \201CSign in to My portal\201D: they see today\2019s attendance and their month, send their requests and see their leave balance. No password of its own: signing in to the organization\2019s systems is enough.')) EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\062F\062E\0644 \0627\0644\0645\0648\0638\0641 \0645\0646 \0628\0648\0627\0628\0629 \0627\0644\0645\0624\0633\0633\0629 \062B\0645 \00AB\0627\0644\062F\062E\0648\0644 \0625\0644\0649 \0628\0648\0627\0628\062A\064A\00BB: \064A\0631\0649 \062D\0636\0648\0631\0647 \0627\0644\064A\0648\0645 \0648\0633\062C\0644\0647 \0627\0644\0634\0647\0631\064A\060C \0648\064A\0631\0633\0644 \0637\0644\0628\0627\062A\0647 \0648\064A\0631\0649 \0631\0635\064A\062F \0625\062C\0627\0632\0627\062A\0647. \0644\0627 \0643\0644\0645\0629 \0645\0631\0648\0631 \062E\0627\0635\0629 \0628\0627\0644\0628\0648\0627\0628\0629: \064A\0643\0641\064A \062F\062E\0648\0644\0647 \0625\0644\0649 \0623\0646\0638\0645\0629 \0627\0644\0645\0624\0633\0633\0629. \0631\0627\0628\0637 \0628\0648\0627\0628\062A\064A \0627\0644\0645\0628\0627\0634\0631: f?p=&APP_ID.:77') AR, 'The employee comes in from the organisation''s portal, then Enter My portal: they see their attendance today and their monthly record, send their requests and see their leave balance. The portal has no password of its own: signing in to the organisation''s systems is enough. My portal''s own address: f?p=&APP_ID.:77' EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\062F\062E\0644\0648\0646 \0628\0628\0631\064A\062F\0647\0645') AR, 'Sign in with their email' EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\062F\062E\0644\0648\0646 \0628\062D\0633\0627\0628 \0645\0631\062A\0628\0637 \0628\0647\0645') AR, 'Sign in with a linked account' EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\062F\0648\064A') AR, 'By hand' EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\0631\0633\0644 \0625\0644\0649 \0627\0644\062C\0647\0627\0632') AR, 'Sending to the terminal' EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\0631\0649 \0645\0633\0624\0648\0644 \0627\0644\0642\0633\0645 \0648\0646\0627\0626\0628\0647 \0637\0644\0628\0627\062A \0627\0644\0625\062C\0627\0632\0629 \0648\0627\0644\0628\0635\0645\0629 \0627\0644\064A\062F\0648\064A\0629 \0648\0627\0644\0639\0645\0644 \0627\0644\0625\0636\0627\0641\064A \0644\0645\0648\0638\0641\064A \0647\0630\0627 \0627\0644\0642\0633\0645 \0648\0627\0644\0623\0642\0633\0627\0645 \0627\0644\062A\0627\0628\0639\0629 \0644\0647\060C \0648\064A\0639\062A\0645\062F\0648\0646\0647\0627\061B \0648\0644\0627 \064A\0631\0648\0646 \0637\0644\0628\0627\062A \063A\064A\0631\0647\0627. \0627\0644\0646\0627\0626\0628 \064A\0639\062A\0645\062F \0641\064A \0641\062A\0631\062A\0647 \0641\0642\0637 (\0641\0627\0631\063A = \062F\0627\0626\0645\0627\064B). \064A\062D\062A\0627\062C \0627\0644\062D\0633\0627\0628 \0623\064A\0636\0627\064B \0635\0644\0627\062D\064A\0629 \00AB\0627\0639\062A\0645\0627\062F \0627\0644\0637\0644\0628\0627\062A\00BB\060C \0648\0627\0644\0645\062F\064A\0631 \0627\0644\0639\0627\0645 \064A\0639\062A\0645\062F \0643\0644 \0627\0644\0623\0642\0633\0627\0645 \062F\0648\0646 \062A\0639\064A\064A\0646. \0627\0644\062D\0633\0627\0628\0627\062A \0645\0646 \0635\0641\062D\0629 \00AB\0627\0644\0645\0633\062A\062E\062F\0645\0648\0646\00BB.') AR, TO_CHAR(UNISTR('A department head and deputy see the leave, manual punch and overtime requests of this department\2019s employees and of the departments under it, and approve them; they see no other requests. A deputy approves only in their period (empty = always). The account also needs the \201CApprove requests\201D permission; the general manager approves all departments without being assigned. Accounts are on the \201CUsers\201D page.')) EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\0633\062A\0642\0628\0644 \0645\0646 \0627\0644\062C\0647\0627\0632') AR, 'Receiving from the terminal' EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\0635\0644 \0627\0644\062C\0647\0627\0632 \0625\0644\0649 \0627\0644\062E\0627\062F\0645 \0645\0646 \0627\0644\0639\0646\0648\0627\0646') AR, 'The terminal reaches the server from the address' EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\0646\062A\0638\0631 \0631\062F \062E\0627\062F\0645 \0627\0644\062F\0648\0627\0645\061B \0627\0636\063A\0637 \00AB\062A\062D\062F\064A\062B\00BB \0628\0639\062F \0642\0644\064A\0644.') AR, TO_CHAR(UNISTR('Waiting for the attendance server\0027s answer; press \00ABRefresh\00BB in a moment.')) EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\0646\062A\0638\0631 \0631\062F \062E\0627\062F\0645 \062D\0627\0636\0631\061B \0627\0636\063A\0637 \00AB\062A\062D\062F\064A\062B\00BB \0628\0639\062F \0642\0644\064A\0644.') AR, TO_CHAR(UNISTR('Waiting for the Hader server\0027s answer; press \00ABRefresh\00BB in a moment.')) EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\064F\062A\0627\0628\0639 \062D\0636\0648\0631\0647') AR, 'Tracked' EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\064F\062E\062A\0628\0631 \0647\0646\0627 \0627\0644\0627\062A\0635\0627\0644 \0628\062E\062F\0645\0629 \062A\064F\0637\0644\0628 \0645\0646 \0642\0627\0639\062F\0629 \0627\0644\0628\064A\0627\0646\0627\062A. \062E\062F\0645\0629 \062A\064F\0637\0644\0628 \0645\0646 \0627\0644\0645\062A\0635\0641\062D \062A\064F\062E\062A\0628\0631 \0628\0633\0624\0627\0644 \0641\064A \00AB\0627\0644\0645\0633\0627\0639\062F \0627\0644\0630\0643\064A\00BB.') AR, TO_CHAR(UNISTR('Here the connection of a service called from the database is tested. A service called from the browser is tested by asking the \00ABAI assistant\00BB a question.')) EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\064F\0642\0627\0633...') AR, 'Measuring...' EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\064F\0646\0634\0623 \0625\0646 \0644\0645 \064A\0648\062C\062F\061B \064A\064F\0643\0641\0649 \0628\0627\0644\0631\0645\0632 \0625\0646 \0648\064F\062C\062F') AR, 'Created if it does not exist; the code alone is enough when given' EN FROM DUAL
UNION ALL SELECT UNISTR('\064A\064F\0646\0641\064E\0651\0630') AR, 'Running' EN FROM DUAL) s ON (t.AR = s.AR)
  WHEN MATCHED THEN UPDATE SET EN = s.EN WHERE t.EN <> s.EN
  WHEN NOT MATCHED THEN INSERT (AR, EN) VALUES (s.AR, s.EN);
  COMMIT;
END;
/

-- ---------------------------------------------------------------- hdr_core.pks
CREATE OR REPLACE PACKAGE HDR_CORE AS
  -- Hader for Oracle APEX (native): settings, text helpers, the terminal command queue and the
  -- distribution of employees, templates and photos to the terminals of their areas.

  TYPE t_kv IS TABLE OF NVARCHAR2(4000) INDEX BY VARCHAR2(60);

  -- the Hader release these objects belong to: the APEX app warns when it is newer than them
  c_version CONSTANT VARCHAR2(20) := '2.4.33';

  -- TRUE while a terminal's upload is stored: the change triggers stay quiet (the upload distributes
  -- what it changes itself and marks its own days)
  g_quiet BOOLEAN := FALSE;

  -- settings ------------------------------------------------------------
  FUNCTION setting (p_key IN VARCHAR2, p_default IN VARCHAR2 DEFAULT NULL) RETURN VARCHAR2;
  PROCEDURE set_setting (p_key IN VARCHAR2, p_value IN VARCHAR2);
  FUNCTION on_ (p_key IN VARCHAR2) RETURN BOOLEAN;           -- a Y/N setting
  FUNCTION writing RETURN BOOLEAN;                           -- changes may be sent to the terminals
  FUNCTION server_tz (p_sn IN VARCHAR2 DEFAULT NULL) RETURN NUMBER;   -- hours, for the terminals
  -- the clock the terminals keep: the database's time in the zone set for the terminal (adms.timezone); the
  -- database's own clock when none is set
  FUNCTION local_now (p_sn IN VARCHAR2 DEFAULT NULL) RETURN DATE;

  -- text ------------------------------------------------------------------
  FUNCTION to_text (p_body IN BLOB) RETURN NCLOB;           -- UTF-8, older Arabic code page per line
  FUNCTION to_utf8 (p_text IN NCLOB) RETURN BLOB;
  FUNCTION kv (p_text IN NVARCHAR2, p_sep IN VARCHAR2 DEFAULT CHR(9)) RETURN t_kv;   -- keys lower-case
  FUNCTION kv_big (p_line IN NCLOB, p_key IN VARCHAR2, p_sep IN VARCHAR2 DEFAULT CHR(9)) RETURN CLOB;
  FUNCTION get (p_kv IN t_kv, p_key IN VARCHAR2, p_default IN NVARCHAR2 DEFAULT NULL) RETURN NVARCHAR2;
  FUNCTION num (p_value IN NVARCHAR2, p_default IN NUMBER DEFAULT 0) RETURN NUMBER;
  FUNCTION parse_time (p_text IN NVARCHAR2) RETURN DATE;
  FUNCTION valid_pin (p_pin IN VARCHAR2) RETURN BOOLEAN;
  FUNCTION field (p_text IN VARCHAR2, p_n IN PLS_INTEGER, p_sep IN VARCHAR2 DEFAULT CHR(9)) RETURN VARCHAR2;  -- n-th, empty ones count
  FUNCTION tsv_safe (p_value IN NVARCHAR2) RETURN NVARCHAR2;  -- no tab / newline inside a value
  FUNCTION dev_time (p_when IN DATE) RETURN NUMBER;           -- the terminals' compact clock value
  FUNCTION b64_blob (p_text IN CLOB) RETURN BLOB;             -- base64 text (line breaks and all) to its bytes

  -- the hours of an employee's working day on a date (hader/day_hours.py): of the rules hr.day_hours_rules that hold
  -- (hours|from|to|attendance type ids|department codes|name, ";" between), the one starting last; else the hours the
  -- employee's attendance type that day has most often; else hr.day_hours (7)
  FUNCTION day_hours (p_emp IN VARCHAR2, p_day IN DATE) RETURN NUMBER;

  -- terminal options (Key=Value lines kept in HDR_DEVICES.OPTIONS) ----------
  FUNCTION opt (p_sn IN VARCHAR2, p_key IN VARCHAR2) RETURN VARCHAR2;
  PROCEDURE apply_info (p_sn IN VARCHAR2, p_info IN t_kv);    -- merge INFO / options keys

  -- command queue -----------------------------------------------------------
  FUNCTION is_change (p_content IN NVARCHAR2) RETURN BOOLEAN;   -- anything but INFO / DATA QUERY
  FUNCTION queue (p_sn IN VARCHAR2, p_content IN NCLOB, p_title IN NVARCHAR2 DEFAULT NULL) RETURN NUMBER;
  PROCEDURE queue (p_sn IN VARCHAR2, p_content IN NCLOB, p_title IN NVARCHAR2 DEFAULT NULL);
  PROCEDURE requeue_stale (p_minutes IN NUMBER DEFAULT 15, p_max_attempts IN NUMBER DEFAULT 3);

  -- command texts -------------------------------------------------------------
  -- as much of a name as a terminal's name field holds (24 bytes: about 12 Arabic letters), never half a letter
  FUNCTION terminal_name (p_name IN NVARCHAR2, p_bytes IN NUMBER DEFAULT 24) RETURN NVARCHAR2;
  FUNCTION whole_words (p_held IN NVARCHAR2, p_full IN NVARCHAR2) RETURN BOOLEAN;
  FUNCTION name_bytes (p_sn IN VARCHAR2) RETURN NUMBER;
  FUNCTION cmd_user (p_emp_code IN VARCHAR2, p_sn IN VARCHAR2 DEFAULT NULL) RETURN NCLOB;
  FUNCTION cmd_user_delete (p_emp_code IN VARCHAR2) RETURN NCLOB;
  FUNCTION cmd_query (p_table IN VARCHAR2, p_pin IN VARCHAR2 DEFAULT NULL) RETURN NCLOB;
  FUNCTION cmd_query_attlog (p_from IN DATE, p_to IN DATE) RETURN NCLOB;

  -- employees on terminals ------------------------------------------------------
  FUNCTION uses_biodata (p_sn IN VARCHAR2) RETURN BOOLEAN;
  FUNCTION push_employee (p_sn IN VARCHAR2, p_emp_code IN VARCHAR2, p_with_bio IN BOOLEAN DEFAULT TRUE) RETURN NUMBER;
  FUNCTION sync_device (p_sn IN VARCHAR2) RETURN NUMBER;     -- every employee of its area (checks capacity)
  FUNCTION employee_changed (p_emp_code IN VARCHAR2, p_old_areas IN VARCHAR2 DEFAULT NULL,
                             p_with_bio IN BOOLEAN DEFAULT FALSE) RETURN NUMBER;   -- p_old_areas: 'id,id'
  FUNCTION employee_removed (p_emp_code IN VARCHAR2, p_areas IN VARCHAR2) RETURN NUMBER;
  -- people, every kind of template and the photos a terminal holds; p_again 'Y' (asked by a person): table
  -- queries tried once more even if the terminal refused them before
  FUNCTION pull_bio (p_sn IN VARCHAR2, p_pin IN VARCHAR2 DEFAULT NULL, p_again IN VARCHAR2 DEFAULT 'N') RETURN NUMBER;
  -- the terminal sends everything it holds again by itself: its marks cleared, its options read again
  FUNCTION resend_everything (p_sn IN VARCHAR2) RETURN NUMBER;
  -- it refused a table query (-1004): remembered, the other queries waiting closed, everything asked the other way
  PROCEDURE no_table_queries (p_sn IN VARCHAR2);
  FUNCTION bio_delete (p_emp_code IN VARCHAR2, p_kinds IN VARCHAR2, p_fingers IN VARCHAR2 DEFAULT NULL,
                       p_terminals IN BOOLEAN DEFAULT TRUE) RETURN NUMBER;
  PROCEDURE distribute_user (p_emp_code IN VARCHAR2, p_source_sn IN VARCHAR2);
  PROCEDURE distribute_template (p_bio_id IN NUMBER, p_source_sn IN VARCHAR2);
  -- The card picture (HADER_EMP_PHOTOS with SOURCE HAND, DEVICE or NULL) is what a terminal shows when the
  -- employee punches. The recognition photo (HDR_BIO_PHOTOS; SOURCE CAPTURE where it stands in on the pages)
  -- is what it learns the face from, and is never sent as the card picture.
  PROCEDURE distribute_userpic (p_emp_code IN VARCHAR2, p_source_sn IN VARCHAR2);
  PROCEDURE withdraw_userpic (p_emp_code IN VARCHAR2, p_source_sn IN VARCHAR2);   -- the terminals drop theirs
  PROCEDURE userpic_back (p_emp_code IN VARCHAR2, p_sn IN VARCHAR2);   -- the chosen one again (not in a loop)
  -- a terminal holding the person without the name kept here (enrolled there by number only) or with another
  -- one is sent it (not in a loop); p_held: the name it holds
  PROCEDURE name_back (p_emp_code IN VARCHAR2, p_sn IN VARCHAR2, p_held IN NVARCHAR2);
  FUNCTION is_recognition_photo (p_emp_code IN VARCHAR2, p_pic IN BLOB) RETURN BOOLEAN;
  PROCEDURE distribute_photo (p_emp_code IN VARCHAR2, p_bio_type IN NUMBER, p_source_sn IN VARCHAR2);
  -- the recognition photo to every terminal of the employee's areas (they learn the face from it); how many
  FUNCTION send_photo (p_emp_code IN VARCHAR2, p_bio_type IN NUMBER DEFAULT 9) RETURN NUMBER;
  PROCEDURE mark_dirty (p_emp_code IN VARCHAR2, p_day IN DATE);
  PROCEDURE mark_days (p_emp_code IN VARCHAR2, p_from IN DATE, p_to IN DATE);   -- past and today only
  PROCEDURE mark_pending (p_kind IN VARCHAR2, p_key IN VARCHAR2, p_added IN VARCHAR2 DEFAULT NULL,
                          p_removed IN VARCHAR2 DEFAULT NULL, p_deleted IN BOOLEAN DEFAULT FALSE,
                          p_from IN DATE DEFAULT NULL);

  -- terminal settings sent as commands ---------------------------------------------
  PROCEDURE set_server (p_sn IN VARCHAR2, p_host IN VARCHAR2, p_port IN NUMBER, p_reboot IN BOOLEAN DEFAULT TRUE);
  PROCEDURE set_clock (p_sn IN VARCHAR2, p_when IN DATE DEFAULT NULL);
  PROCEDURE simple (p_sn IN VARCHAR2, p_action IN VARCHAR2);  -- info, check, reboot, clear_log, clear_photo, clear_data
  PROCEDURE set_option (p_sn IN VARCHAR2, p_key IN VARCHAR2, p_value IN NVARCHAR2);
  PROCEDURE enroll (p_sn IN VARCHAR2, p_emp_code IN VARCHAR2, p_bio_type IN NUMBER, p_finger IN NUMBER DEFAULT 0);

  -- errors raised to APEX pages
  e_read_only EXCEPTION;
  PRAGMA EXCEPTION_INIT (e_read_only, -20601);
  e_capacity EXCEPTION;
  PRAGMA EXCEPTION_INIT (e_capacity, -20602);
END HDR_CORE;
/

