CREATE OR REPLACE TRIGGER HDR_LEAVES_TOLD
AFTER UPDATE OF STATUS ON HDR_LEAVES FOR EACH ROW
WHEN (OLD.STATUS = 'pending' AND NEW.STATUS IN ('approved', 'rejected'))
BEGIN
  INSERT INTO HDR_EMP_NOTES (EMP_CODE, KIND, TITLE, BODY)
  VALUES (:NEW.EMP_CODE, 'request_decided',
          CASE WHEN :NEW.STATUS = 'approved' THEN UNISTR('\062A\0645\062A \0627\0644\0645\0648\0627\0641\0642\0629 \0639\0644\0649 \0637\0644\0628\0643') ELSE UNISTR('\0631\064F\0641\0636 \0637\0644\0628\0643') END,
          SUBSTR(UNISTR('\0625\062C\0627\0632\0629') || ' ' || TO_CHAR(:NEW.START_TIME, 'YYYY-MM-DD HH24:MI') || ' - ' || TO_CHAR(:NEW.END_TIME, 'YYYY-MM-DD HH24:MI')
                 || CASE WHEN :NEW.DECISION_NOTE IS NOT NULL THEN UNISTR(' - ') || :NEW.DECISION_NOTE END, 1, 1000));
END;
/
CREATE OR REPLACE TRIGGER HDR_MANUAL_PUNCHES_TOLD
AFTER UPDATE OF STATUS ON HDR_MANUAL_PUNCHES FOR EACH ROW
WHEN (OLD.STATUS = 'pending' AND NEW.STATUS IN ('approved', 'rejected'))
BEGIN
  INSERT INTO HDR_EMP_NOTES (EMP_CODE, KIND, TITLE, BODY)
  VALUES (:NEW.EMP_CODE, 'request_decided',
          CASE WHEN :NEW.STATUS = 'approved' THEN UNISTR('\062A\0645\062A \0627\0644\0645\0648\0627\0641\0642\0629 \0639\0644\0649 \0637\0644\0628\0643') ELSE UNISTR('\0631\064F\0641\0636 \0637\0644\0628\0643') END,
          SUBSTR(UNISTR('\062A\0635\062D\064A\062D \0628\0635\0645\0629') || ' ' || TO_CHAR(:NEW.PUNCH_TIME, 'YYYY-MM-DD HH24:MI')
                 || CASE WHEN :NEW.DECISION_NOTE IS NOT NULL THEN UNISTR(' - ') || :NEW.DECISION_NOTE END, 1, 1000));
END;
/
CREATE OR REPLACE TRIGGER HDR_OVERTIME_TOLD
AFTER UPDATE OF STATUS ON HDR_OVERTIME FOR EACH ROW
WHEN (OLD.STATUS = 'pending' AND NEW.STATUS IN ('approved', 'rejected'))
BEGIN
  INSERT INTO HDR_EMP_NOTES (EMP_CODE, KIND, TITLE, BODY)
  VALUES (:NEW.EMP_CODE, 'request_decided',
          CASE WHEN :NEW.STATUS = 'approved' THEN UNISTR('\062A\0645\062A \0627\0644\0645\0648\0627\0641\0642\0629 \0639\0644\0649 \0637\0644\0628\0643') ELSE UNISTR('\0631\064F\0641\0636 \0637\0644\0628\0643') END,
          SUBSTR(UNISTR('\0639\0645\0644 \0625\0636\0627\0641\064A') || ' ' || TO_CHAR(:NEW.START_TIME, 'YYYY-MM-DD HH24:MI') || ' - ' || TO_CHAR(:NEW.END_TIME, 'HH24:MI')
                 || CASE WHEN :NEW.DECISION_NOTE IS NOT NULL THEN UNISTR(' - ') || :NEW.DECISION_NOTE END, 1, 1000));
END;
/

-- ---------------------------------------------------------------- hdr_scheduler.sql
BEGIN
  BEGIN
    DBMS_SCHEDULER.DROP_JOB('HDR_TICK', force => TRUE);
  EXCEPTION WHEN OTHERS THEN
    IF SQLCODE <> -27475 THEN
      RAISE;
    END IF;
  END;
  DBMS_SCHEDULER.CREATE_JOB(
    job_name        => 'HDR_TICK',
    job_type        => 'PLSQL_BLOCK',
    job_action      => 'BEGIN HDR_JOBS.tick; END;',
    start_date      => SYSTIMESTAMP,
    repeat_interval => 'FREQ=MINUTELY;INTERVAL=1',
    enabled         => TRUE,
    comments        => 'Hader: terminals, attendance calculation, HR import, requests');
END;
/

-- ---------------------------------------------------------------- done
DECLARE
  n NUMBER;
BEGIN
  MERGE INTO HDR_SETTINGS t USING (SELECT 'maintenance' k FROM DUAL) s ON (t.SKEY = s.k)
  WHEN MATCHED THEN UPDATE SET SVALUE = 'N' WHEN NOT MATCHED THEN INSERT (SKEY, SVALUE) VALUES (s.k, 'N');
  BEGIN
    EXECUTE IMMEDIATE 'BEGIN HDR_CORE.set_setting(''schema.version'', HDR_CORE.c_version); END;';
  EXCEPTION WHEN OTHERS THEN
    NULL;   -- HDR_CORE does not compile: counted below
  END;
  COMMIT;
  SELECT COUNT(*) INTO n FROM user_errors WHERE name LIKE 'HDR%' OR name LIKE 'HADER%';
  DBMS_OUTPUT.PUT_LINE('Hader for Oracle APEX: ' || n || ' compile errors (workshop/3_verify.sql lists them)');
END;
/
